public class Main {
    public static void main(String[] args) {
        Shape[] shapes = {new Rectangle(4, 5), new Square(3)};
        for (Shape s : shapes) {
            s.print();
        }
    }
}

abstract class Shape {
    abstract String name();

    abstract int area();

    void print() {
        System.out.println(name() + " area: " + area());
    }
}

class Rectangle extends Shape {
    private final int width, height;

    Rectangle(int width, int height) {
        this.width = width;
        this.height = height;
    }

    String name() {
        return "Rectangle";
    }

    int area() {
        return width * height;
    }
}

class Square extends Shape {
    private final int side;

    Square(int side) {
        this.side = side;
    }

    String name() {
        return "Square";
    }

    int area() {
        return side * side;
    }
}
